/* ── 2. 字体 ─────────────────────────────────────────── */
/* ============================================================
   字体：整段放最末尾（保证不被任何规则抢先）
   ============================================================ */
@font-face{font-family:'HuiwenMincho';src:url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/Huiwen-mincho.woff2") format("woff2");font-display:swap;}
@font-face{font-family:'JVSignature';src:url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/JVSignatureSVG.woff2") format("woff2");font-display:swap;}
html body,
html body #chat,
html body input,
html body textarea,
html body .text_pole,
html body .ch_name,
html body .menu_button,
html body .standoutHeader{
  font-family:'HuiwenMincho','Songti SC','STSong',serif !important;
}
html body .mes_text{
  font-family:'JVSignature','HuiwenMincho','Songti SC',serif !important;
}
/* 新增：正文用的英文手写体（三选一，留一行即可） */
@font-face{
  font-family:'Caveat';
  src:url("https://cdn.jsdelivr.net/npm/@fontsource/caveat/files/caveat-latin-400-normal.woff2") format("woff2");
  font-display:swap;
}
/* @font-face{
  font-family:'Kalam';
  src:url("https://cdn.jsdelivr.net/npm/@fontsource/kalam/files/kalam-latin-400-normal.woff2") format("woff2");
  font-display:swap;
} */
/* @font-face{
  font-family:'Patrick Hand';
  src:url("https://cdn.jsdelivr.net/npm/@fontsource/patrick-hand/files/patrick-hand-latin-400-normal.woff2") format("woff2");
  font-display:swap;
} */

/* 正文：英文走新手写体，中文照旧落明朝（这行只改第一顺位） */
html body .mes_text{
  font-family:'Caveat','HuiwenMincho','Songti SC',serif !important;
}
/* ── 3. 图标字体保护 ─────────────────────────────────── */
html body [class*="fa-"],
html body [class^="fa-"],
html body [class*="fa-"]::before,
html body [class^="fa-"]::before,
html body [class*="fa-"]::after,
html body [class^="fa-"]::after{
  font-family:"Font Awesome 6 Free" !important;
}
.fa-solid, .fa-solid::before{ font-weight:900 !important; }
.fa-regular, .fa-regular::before{ font-weight:400 !important; }
.fa-brands, .fa-brands::before{ font-family:"Font Awesome 6 Brands" !important; }

/* ── 4. 全局底色 + 背景 ──────────────────────────────── */
body, #chat{ background-color:#e8ebed !important; color:#2b3135 !important; }
body, html, #chat{
  background-image:
    url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/flyingbirds.png"),
    url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/bg01.png") !important;
  background-size:cover, cover !important;
  background-position:center, center !important;
  background-repeat:no-repeat, no-repeat !important;
  background-attachment:fixed, fixed !important;
}

/* ── 5. 面板基底：先清掉酒馆的深色底纹 ───────────────── */
.inline-drawer, .inline-drawer-header, .inline-drawer-toggle,
.inline-drawer-content, .inline-drawer-outlet,
.drawer, .drawer-content, .drawer-header, .standoutHeader{
  background:#e8ebed !important;
  background-image:none !important;
  color:#2b3135 !important;
  border-color:#b8c2c7 !important;
}
html body .drawer-content,
html body .drawer-content::before,
html body .drawer-content::after{ background-image:none !important; }
html body .drawer-content *:not([class*="bg_"]):not([class*="thumbnail"]),
html body .drawer-content *:not([class*="bg_"]):not([class*="thumbnail"])::before,
html body .drawer-content *:not([class*="bg_"]):not([class*="thumbnail"])::after{ background-image:none !important; }

/* ── 6. 统一"不透明底 + 白纱"（菜单 / 面板 / 查看器 / 弹窗） ── */
html body #options,
html body #extensionsMenu,
html body .drawer > .drawer-content,
html body #top-settings-holder .drawer-content{
  background-color:#e8ebed !important;
  background-image:
    linear-gradient(rgba(232,235,237,.60), rgba(232,235,237,.60)),
    url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/bg01.png") !important;
  background-size:cover, cover !important;
  background-position:center, center !important;
  background-repeat:no-repeat, no-repeat !important;
  background-clip:padding-box !important;
  color:#2b3135 !important;
  border:1px solid #b8c2c7 !important;
  border-radius:3px !important;
  box-shadow:0 3px 14px rgba(40,60,70,.18) !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
}
/* 面板本体（菜单另给 padding，见第 16 节） */
html body .drawer > .drawer-content,
html body #top-settings-holder .drawer-content{ padding:10px 12px !important; }

/* 查看器类面板（提示词 / 宏 / 数据管理） */
html body [class*="prompt_manager"],
html body [class*="macroBrowser"],
html body [class*="macro-list-panel"],
html body [class*="macro-container"],
html body [class*="macro-details-panel"],
html body [class*="dataMaid"]{
  background-color:#e8ebed !important;
  background-image:
    linear-gradient(rgba(232,235,237,.62), rgba(232,235,237,.62)),
    url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/bg01.png") !important;
  background-size:cover, cover !important;
  background-position:center, center !important;
  background-repeat:no-repeat, no-repeat !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
}
/* 通用弹窗：只给"框"上色，全屏那层不动 */
