/* ============================================================
   聊天区滚动条：右边固定留位（不再两边留、不再动 #sheld）
   ============================================================ */
html body #chat{
  scrollbar-gutter:stable !important;    /* 只在右边留；without both-edges */
}
/* 兼容老内核：不支持 scrollbar-gutter 时，用"常驻滚动条"达到同样效果 */
@supports not (scrollbar-gutter: stable){
  html body #chat{
    overflow-y:scroll !important;        /* 条一直在 → 宽度恒定 */
  }
}
/* 右边常留一根条的宽 → 内容中心固定偏左半根(5px)。
   左边补一整根(10px)，中心就回到正中，和顶栏那张素材重新对上。 */
html body #chat{
  margin-left:15px !important;           /* 5px(原) + 10px(滚动条宽) */
  margin-right:5px !important;
}
/* ============================================================
   滚动条 · 雾白底上的墨色小药丸
   ⚠️ 宽度保持 10px —— 一改，#chat 那句 margin-left:15px 也要跟着改
   ============================================================ */
::-webkit-scrollbar{ width:10px !important; height:10px !important; }

/* 轨道：全透明，不留任何底色/描边 */
::-webkit-scrollbar-track,
::-webkit-scrollbar-track:hover,
::-webkit-scrollbar-corner{
  background:transparent !important;
  border:0 !important;
  box-shadow:none !important;
}

/* 滑块：透明边框 + content-box → 视觉上比轨道窄 4px，得到"浮在中间"的效果 */
::-webkit-scrollbar-thumb{
  background-color:rgba(43,49,53,.20) !important;    /* 墨色 20%，平时很淡 */
  border:3px solid transparent !important;           /* 透明，不是描边 */
  background-clip:content-box !important;
  border-radius:10px !important;
  min-height:48px !important;                        /* 再短也拖得住 */
  transition:background-color .18s ease !important;
}
/* 干掉两端那些小箭头/按钮（安卓上容易露出一小块方块） */
::-webkit-scrollbar-button{
  display:none !important;
  width:0 !important; height:0 !important;
}
