/* 输入栏左侧两颗（调色盘、魔法棒）：跟顶栏"关着"的图标一个深浅 */
html body #options_button,
html body #extensionsMenuButton{
  opacity:.30 !important;
  transition:opacity .16s ease !important;
}
html body #options_button:hover,
html body #extensionsMenuButton:hover{
  opacity:30 !important;
}
/* ── 15. 顶栏（栏 + 装饰 + 图标） ────────────────────── */
html body .drawer,
html body .drawer-toggle{
  background:transparent !important; background-image:none !important; box-shadow:none !important;
}
html body #top-settings-holder,
html body div:has(> .drawer){
  background-color:transparent !important;
  background-image:url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/bg01.png") !important;
  background-repeat:no-repeat !important;
  background-position:center !important;
  background-size:cover !important;
  border:0 !important;
  border-bottom:2px dotted #c3ccd0 !important;
  box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
}
html body #top-settings-holder::after,
html body div:has(> .drawer)::after{
  content:""; position:absolute !important;
  left:52% !important; top:-55% !important; bottom:0 !important;
  transform:translateX(-50%) !important;
  width:100px !important; height:100px !important;
  background:url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/BlackLily04.jpg") center/contain no-repeat !important;
  opacity:.5 !important; pointer-events:none !important; z-index:1000 !important;
}
html body .drawer-icon{
  position:relative !important; z-index:1001 !important;
  font-size:var(--mainFontSize,15px) !important;
  width:2em !important; height:2em !important; padding:0 !important;
  display:flex !important; align-items:center !important; justify-content:center !important;
}
html body .drawer-icon::before{
  content:"" !important; display:block !important;
  width:var(--nav-size) !important; height:var(--nav-size) !important;
  margin:auto !important;
  background-repeat:no-repeat !important;
  background-position:center !important;
  background-size:contain !important;
}
html body .drawer-icon.fa-sliders::before                 { background-image:var(--ic-set) !important; }
html body .drawer-icon.fa-plug::before,
html body .drawer-icon.fa-plug-circle-exclamation::before { background-image:var(--ic-api) !important; }
html body .drawer-icon.fa-cubes::before                   { background-image:var(--ic-ext) !important; }
html body .drawer-icon.fa-book-atlas::before              { background-image:var(--ic-world) !important; }
html body .drawer-icon.fa-font::before                    { background-image:var(--ic-format) !important; }
html body .drawer-icon.fa-face-smile::before              { background-image:var(--ic-persona) !important; }
html body .drawer-icon.fa-address-card::before            { background-image:var(--ic-card) !important; }
html body .drawer-icon.fa-panorama::before                { background-image:var(--ic-image) !important; }
html body .drawer-icon.fa-user-cog::before                { background-image:none !important; }   /* 隐藏用户设置图标 */

/* ── 16. 弹出菜单 #options / #extensionsMenu（内容排版） ── */
html body #options,
html body #extensionsMenu{ padding:6px !important; }
html body #options .options-content,
html body #options .options-content-inner,
html body #extensionsMenu .extension_container{
  background:transparent !important; background-image:none !important;
  border:none !important; box-shadow:none !important;
}
html body #options .menu_button,
html body #extensionsMenu .menu_button{
  background-color:transparent !important; background-image:none !important;
  color:#2b3135 !important;
  border:0 !important;
  border-bottom:1px dashed #c3ccd0 !important;
  border-radius:0 !important;
  box-shadow:none !important; text-shadow:none !important;
  text-align:left !important;
  padding:7px 10px !important;
  letter-spacing:.02em !important;
  transition:background-color .16s ease, color .16s ease !important;
}
html body #options .menu_button:last-child,
html body #extensionsMenu .menu_button:last-child{ border-bottom:0 !important; }
html body #options .menu_button:hover,
html body #extensionsMenu .menu_button:hover{
  background-color:rgba(20,105,132,.09) !important;
  color:#146984 !important;
}
html body #options .menu_button i,
html body #extensionsMenu .menu_button i,
html body #options .menu_button [class*="fa-"],
html body #extensionsMenu .menu_button [class*="fa-"]{
  color:#526d78 !important; opacity:.9 !important;
}
html body #options .menu_button:hover i,
html body #extensionsMenu .menu_button:hover i{ color:#146984 !important; opacity:1 !important; }
html body #options h3, html body #options h4,
html body #extensionsMenu h3, html body #extensionsMenu h4{
  color:#2b3135 !important; font-weight:400 !important;
  letter-spacing:.14em !important; text-shadow:none !important;
  margin:4px 2px 6px !important;
}
html body #options small,
html body #extensionsMenu small{ color:#4a5a63 !important; text-shadow:none !important; }

/* ── 17. 角色卡列表 ──────────────────────────────────── */
html body #rm_print_characters_block{
  display:flex !important; flex-flow:column nowrap !important;
  gap:8px !important; padding:10px !important;
  background:transparent !important;
}
html body #rm_print_characters_block .character_select{
  display:flex !important; flex-flow:row nowrap !important;
  align-items:center !important; gap:12px !important;
  padding:10px !important; margin:0 !important;
  background:rgba(255,255,255,.55) !important;
  border:1px solid #d3dade !important;
  border-bottom:1px solid #d3dade !important;
  border-radius:3px !important;
  box-shadow:none !important;
  transition:background-color .16s ease, border-color .16s ease !important;
}
html body #rm_print_characters_block .character_select:hover{
  background:rgba(255,255,255,.85) !important;
  border-color:#93a4ac !important;
}
html body #rm_print_characters_block .character_select .ch_name{
  flex:1 1 auto !important; min-width:0 !important;
  display:flex !important; flex-flow:column nowrap !important;
  align-items:flex-start !important; text-align:left !important; gap:3px !important;
}
html body #rm_print_characters_block .character_select .character_name,
html body .character_select .character_name{
  color:#2b3135 !important;
  font-size:calc(var(--mainFontSize,15px) * 1.1) !important;
  letter-spacing:.08em !important;
  white-space:nowrap !important; overflow:hidden !important;
  text-overflow:ellipsis !important; max-width:100% !important;
}
html body #rm_print_characters_block .character_select .character_description,
html body .character_select .character_description{
  color:#55656e !important;
  font-size:calc(var(--mainFontSize,15px) * .84) !important;
  line-height:1.55 !important;
  display:-webkit-box !important;
  -webkit-line-clamp:2 !important; -webkit-box-orient:vertical !important;
  overflow:hidden !important;
}
html body .character_select .tag,
html body .character_select span.tag{
  background:rgba(20,105,132,.08) !important;
  color:#3f5c68 !important;
  border:1px solid rgba(20,105,132,.18) !important;
  border-radius:2px !important;
  padding:1px 6px !important;
  font-size:calc(var(--mainFontSize,15px) * .78) !important;
  letter-spacing:.02em !important;
  margin:1px 2px 1px 0 !important;
}
html body .character_select .character_version{ display:none !important; }
/* 头像：无框无影，只留图片 */
html body .character_select .avatar,
html body #rm_print_characters_block .character_select .avatar{
  flex:0 0 auto !important;
  width:56px !important; height:56px !important;
  border:0 !important; box-shadow:none !important;
  border-radius:4px !important;
  background-size:cover !important; background-position:center !important;
}
/* 右侧按钮：平时淡，悬停亮 */
html body #rm_print_characters_block .character_select i,
html body #rm_print_characters_block .character_select [class*="fa-"]{
  color:#7d8b93 !important; opacity:.6 !important;
  transition:color .15s ease, opacity .15s ease !important;
}
html body #rm_print_characters_block .character_select:hover i,
html body #rm_print_characters_block .character_select:hover [class*="fa-"]{
  color:#146984 !important; opacity:1 !important;
}
html body #rm_print_characters_block .character_select .fav_on{ color:#b5432a !important; opacity:1 !important; }
html body .drawer-content .menu_button{ letter-spacing:.02em !important; }
/* 搜索框：底线式 */
html body .drawer-content input#rm_search_characters,
html body .drawer-content .search-bar input{
  background:transparent !important;
  border:0 !important;
  border-bottom:1px dashed #b9c4c9 !important;
  border-radius:0 !important;
  padding:4px 6px !important;
}

/* ── 18. 用户设定面板 ───────────────────────────────── */
html body .drawer-content .flex-container,
html body .drawer-content .flexFlowColumn{ row-gap:6px !important; }
html body .drawer-content label,
html body .drawer-content .range-block-title{
  color:#2b3135 !important; letter-spacing:.03em !important; font-weight:400 !important;
}
html body .drawer-content label small,
html body .drawer-content .range-block-counter{ color:#7d8b93 !important; letter-spacing:0 !important; }
html body .drawer-content input[type="checkbox"],
html body .drawer-content input[type="radio"]{
  width:14px !important; height:14px !important;
  border-radius:2px !important;
  accent-color:#146984 !important;
}

/* ── 19. 图标换皮（放大镜 / ☰） ─────────────────────── */
html body [class*="fa-magnifying-glass"]:not(#_x_),
html body [class*="fa-search"]:not(#_x_){
  color:transparent !important;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256' fill='none' stroke='%232b3135' stroke-width='16' stroke-linecap='round'><circle cx='112' cy='112' r='72'/><path d='M164,164l60,60'/></svg>") center/contain no-repeat !important;
}
html body .drawer-content [class*="fa-bars"]:not(#_x_),
html body .drawer-content [class*="fa-list"]:not(#_x_),
html body .drawer-content [class*="fa-ellipsis"]:not(#_x_){
  color:transparent !important;
  background:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256' fill='none' stroke='%232b3135' stroke-width='18' stroke-linecap='round'><path d='M40,64h176M40,128h176M40,192h176'/></svg>") center/contain no-repeat !important;
}

/* ── 20. 翻页箭头 + 页码 ─────────────────────────────── */
html body .swipe_left,
html body .swipe_right{
  color:transparent !important;
  background-color:transparent !important;
  background-repeat:no-repeat !important;
  background-position:center !important;
  background-size:contain !important;
  border:0 !important; box-shadow:none !important;
  width:1.2em !important; height:1.2em !important; min-width:1.2em !important;
  display:inline-flex !important;
  align-items:center !important; justify-content:center !important;
  opacity:1 !important;
  transform:translateY(26px) !important;          /* 下移到卡片下方 */
}
html body .swipe_left{  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%232b3135' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M15,6L9,12l6,6'/></svg>") !important; }
html body .swipe_right{ background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%232b3135' stroke-width='2.2' stroke-linecap='round' stroke-linejoin='round'><path d='M9,6l6,6l-6,6'/></svg>") !important; }
html body .swipe_left i, html body .swipe_left svg,
html body .swipe_right i, html body .swipe_right svg{ display:none !important; }
html body .swipes-counter{
  color:#2b3135 !important;
  font-size:calc(var(--mainFontSize,15px) * .9) !important;
  letter-spacing:.06em !important;
  opacity:1 !important;
  text-shadow:none !important;
}

