   ============================================================ */
html body .recentChatList .chatName{
  font-size:0 !important;          /* ← 整行归零 */
  letter-spacing:0 !important;     /* 字号 0 时字距会留白，必须一起清 */
  word-spacing:0 !important;
  display:block !important;
  white-space:nowrap !important;
  overflow:hidden !important;
  text-overflow:ellipsis !important;
  max-width:100% !important;
}
html body .recentChatList .characterName{
  font-size:calc(var(--mainFontSize,15px) * .95) !important;   /* ← 只把名字放回来 */
  color:#2b3135 !important;
  letter-spacing:.05em !important;
  text-shadow:none !important;
}
/* 缺头像占位：只留我们这张，酒馆那层全藏掉 */
html body .missing-avatar{
  background-image:url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/camera.jpg") !important;
  background-size:150% !important;                 /* 放大量 */
  background-position:center !important;
  background-repeat:no-repeat !important;
}
html body img.missing-avatar{
  content:url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/camera.jpg") !important;
  object-fit:cover !important; transform:scale(1.15) !important;
}
html body .missing-avatar > *{ display:none !important; }
html body .missing-avatar::before,
html body .missing-avatar::after{ display:none !important; }
html body .missing-avatar img,
html body .missing-avatar svg{ display:none !important; }

/* ── 22. 开屏 / 加载界面 ─────────────────────────────── */
/* ① 两层遮罩一起改（只改一层会漏出后景） */
#preloader, #loader{
  position:fixed !important;
  inset:0 !important;
  width:100vw !important; height:100vh !important;
  margin:0 !important;
  display:flex !important;
  flex-direction:column !important;
  align-items:center !important;
  justify-content:center !important;
  text-align:center !important;
  gap:1.2rem !important;
  border:0 !important; border-radius:0 !important;
  background-color:#e8ebed !important;
  background-image:url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%276%27%20height%3D%276%27%3E%3Ccircle%20cx%3D%271%27%20cy%3D%271%27%20r%3D%270.6%27%20fill%3D%27%23b8c2c7%27%20opacity%3D%270.35%27%2F%3E%3C%2Fsvg%3E") !important;
  background-size:6px 6px !important;
  box-shadow:none !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
  outline:1px dashed rgba(184,194,199,.95) !important;
  outline-offset:-16px !important;
  opacity:1 !important;
}
#loader{ z-index:99998 !important; }
/* ② 装 loader 的 dialog */
dialog:has(#loader){
  background:transparent !important; border:0 !important;
  box-shadow:none !important; backdrop-filter:none !important;
}
dialog:has(#loader)::backdrop{
  background:#e8ebed !important;
  backdrop-filter:none !important; -webkit-backdrop-filter:none !important;
}
/* ③ 酒馆 logo：整块隐藏 */
#preloader .splash-logo,
#loader .splash-logo,
.splash-logo,
#preloader .splash-logo img,
#loader .splash-logo img,
#preloader img,
#loader img{ display:none !important; }
/* ④ 转圈图：birdring，几何居中（不碰 transform，免得与旋转打架） */
#load-spinner{
  position:static !important;      /* ← 关键：回到正常流，交给 #loader 居中 */
  inset:auto !important;           /* 清掉 fixed 时代的留位 */
  margin:0 auto !important;
  flex:0 0 auto !important;
  order:1 !important;              /* 排在文字上面 */
  display:block !important;
  width:var(--bird-spin-size) !important;
  height:var(--bird-spin-size) !important;
  background:url("https://cdn.jsdelivr.net/gh/Pyroeis13/PMG-st-assets@main/birdring.png") center center / contain no-repeat !important;
  border-radius:50% !important;
  animation:bird-spin var(--bird-spin-speed) linear infinite !important;
  filter:none !important;
}
#load-spinner::before{ content:"" !important; display:none !important; }
#load-spinner i, #load-spinner svg{ display:none !important; }
@keyframes bird-spin{ to{ transform:rotate(360deg); } }
/* ⑤ 文案：英文一行 + 中文一行 */
.splash-message{
  display:block !important;
  width:100% !important;
  text-align:center !important;
  margin-left:auto !important; margin-right:auto !important;
  font-size:0 !important;                          /* 原字整个收掉 */
  order:2 !important;              /* 排在转圈图下面 */
}
.splash-message::before{
  content:"a quiet room at the edge of winter";
  display:block;
  font-family:'JVSignature','HuiwenMincho','Songti SC',serif !important;
  font-size:calc(var(--mainFontSize,15px) * .8) !important;
  color:#93a4ac !important; letter-spacing:.2em !important;
  margin-bottom:.55em !important;
  text-align:center !important;
}
.splash-message::after{
  content:"正在翻越山谷......";
  display:block;
  font-family:'HuiwenMincho','Songti SC','STSong',serif !important;
  font-size:calc(var(--mainFontSize,15px) * 1.05) !important;
  color:#526d78 !important; letter-spacing:.22em !important;
  text-align:center !important;
}
/* 页码 1/3 —— 跟着箭头一起往下带，别叠在一起 */
html body .swipes-counter{
  color:#2b3135 !important;
  font-size:calc(var(--mainFontSize,15px) * .9) !important;
  letter-spacing:.06em !important;
  opacity:1 !important;
  text-shadow:none !important;
  transform:translateY(20px) !important;   /* ← 旋钮：要比箭头的 26 大 */
}
/* Markdown 图标：品牌字体缺字形 → 自绘 */
html body [class*="fa-markdown"]:not(#_x_){
  color:transparent !important;
  background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='%232b3135'><path d='M22.27 19.385H1.73A1.73 1.73 0 010 17.655V6.345a1.73 1.73 0 011.73-1.73h20.54A1.73 1.73 0 0124 6.345v11.308a1.73 1.73 0 01-1.73 1.73zM5.769 15.923v-4.5l2.308 2.885 2.307-2.885v4.5h2.308V8.078h-2.308l-2.307 2.885-2.308-2.885H3.46v7.847zm11.307-1.73l3.462-3.462h-2.307v-4.5h-2.308v4.5h-2.307z'/></svg>") !important;
  background-repeat:no-repeat !important;
  background-position:center !important;
  background-size:contain !important;
  width:1.15em !important;
  height:1.15em !important;
  display:inline-block !important;
  vertical-align:-.12em !important;
}
/* ============================================================
   正文里的几种文本样式：引用 / 斜体 / 加粗 / 删除线 / 标签 / 虚线
   ============================================================ */

/* 斜体：墨蓝，别太跳 */
html body .mes_text em,
html body .mes_text i{
  font-style:italic !important;
  color:#146984 !important;
  letter-spacing:.02em !important;
}

/* 加粗：加重，保持墨色 */
html body .mes_text strong,
html body .mes_text b{
  font-weight:600 !important;
  color:#2b3135 !important;
  letter-spacing:.02em !important;
}

/* 删除线：压淡 + 一条细线 */
html body .mes_text del,
html body .mes_text s,
html body .mes_text strike{
  color:#9aa6ad !important;
  text-decoration:line-through !important;
  text-decoration-color:#b8c2c7 !important;
  text-decoration-thickness:1px !important;
}

html body .mes_text blockquote{
  position:relative !important;
  display:table !important;
  max-width:100% !important;
  box-sizing:border-box !important;
  margin:.7em 0 !important;
  padding:.3em 1em !important;
  line-height:1.65 !important;

  border:1px solid transparent !important;     /* ← 给渐变边留出这 1px */
  border-radius:999px !important;              /* ← 圆气泡 */

  background:
    linear-gradient(#ffffff,#ffffff) padding-box,
    linear-gradient(90deg,
      rgba(65,76,57,0)    0%,
      rgba(65,76,57,.40) 24%,
      rgba(65,76,57,.40) 76%,
      rgba(65,76,57,0)  100%) border-box !important;

  color:#414c39 !important;
  font-style:normal !important;
  letter-spacing:.02em !important;
  box-shadow:none !important;
}
html body .mes_text blockquote p{ margin:0 !important; }
background:
  linear-gradient(90deg,
    rgba(65,76,57,0),
    rgba(65,76,57,.06) 50%,
    rgba(65,76,57,0)) padding-box,
  linear-gradient(#ffffff,#ffffff) padding-box,
  linear-gradient(90deg,
    rgba(65,76,57,0)    0%,
    rgba(65,76,57,.40) 24%,
    rgba(65,76,57,.40) 76%,
    rgba(65,76,57,0)  100%) border-box !important;
}
html body .mes_text q{
  quotes:"「" "」" !important;   /* ← 引号由 CSS 生成 */
  color:#b5432a !important;
  font-style:normal !important;
}
